<style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#182230;font-family:Inter,system-ui,-apple-system,sans-serif}.wrap{max-width:850px;margin:auto;padding:24px 16px 70px}.back{color:#526df5;text-decoration:none;font-weight:750}.card{background:#fff;border:1px solid #e7eaf0;border-radius:22px;padding:26px;margin-top:20px;box-shadow:0 10px 30px #1018280a}.pill{display:inline-block;background:#eef1ff;color:#4459c5;padding:6px 10px;border-radius:99px;font-size:12px;font-weight:850}.head{display:flex;justify-content:space-between;gap:15px;align-items:start}.reward{background:#ecfdf3;color:#087a48;padding:9px 12px;border-radius:12px;font-weight:850}h1{font-size:28px;margin:14px 0 7px}p{color:#667085;line-height:1.65}.meta{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:22px 0}.meta div{background:#f8f9fc;border-radius:14px;padding:15px}.meta small{display:block;color:#98a2b3;margin-bottom:5px}.btn{display:block;width:100%;border:0;border-radius:13px;padding:14px;background:linear-gradient(125deg,#526df5,#7358f6);color:#fff;font-weight:800;font-size:16px}.started{background:#ecfdf3;color:#087a48;padding:16px;border-radius:14px;font-weight:750}.appbox{margin-top:16px;padding:18px;border:1px solid #dfe4ff;background:#f7f8ff;border-radius:16px}.appbox h3{margin:0 0 6px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.appbtn{display:block;text-align:center;text-decoration:none;border-radius:12px;padding:13px;font-weight:800}.openapp{background:#182230;color:#fff}.install{background:#eef1ff;color:#4459c5}.hint{font-size:12px;color:#667085;margin:10px 0 0}@media(max-width:520px){.actions{grid-template-columns:1fr}}.token{font-family:monospace;word-break:break-all;color:#475467;font-size:12px;margin-top:7px}@media(max-width:520px){.card{padding:20px}.head{display:block}.reward{display:inline-block;margin-top:10px}h1{font-size:24px}}</style></head><body><main class="wrap"><a class="back" href="{{ route('worker.dashboard') }}">← Back to dashboard</a><section class="card"><div class="head"><div><span class="pill">{{ strtoupper($task->type) }}</span><h1>{{ $task->title }}</h1></div><span class="reward">${{ number_format((float)$task->reward,2) }}</span></div><p>{{ $task->description }}</p><div class="meta"><div><small>Time slot</small><strong>{{ ucfirst($task->slot) }}</strong></div><div><small>Required Android app</small><strong>{{ $task->app_name ?: 'Assigned utility app' }}</strong></div></div>@if($task->requirements)<div class="meta">@foreach($task->requirements as $key=>$value)<div><small>{{ ucfirst(str_replace('_',' ',$key)) }}</small><strong>{{ $value }}</strong></div>@endforeach</div>@endif
